# e2e_test_selenium.py – Selenium E2E test for Diethive backend UI\n\n"""\nThis test uses Selenium with Chrome (via webdriver‑manager) and pytest.\nIt starts the Flask server in the background, opens the web UI, performs:\n  1️⃣ Login (POST /login) to obtain a JWT.\n  2️⃣ Store the JWT in a browser cookie (HttpOnly not set in dev, we use localStorage).\n  3️⃣ Visit the habits page (GET /habits) and verify the response contains JSON with a ``status": "success"`` field.\n  4️⃣ Logout by clearing the token.\n\nRun with: ``pytest -s e2e_test_selenium.py``.\n"""\n\nimport os, subprocess, time, json\nimport pytest\nfrom selenium import webdriver\nfrom selenium.webdriver.chrome.service import Service as ChromeService\nfrom selenium.webdriver.common.by import By\nfrom selenium.webdriver.support.ui import WebDriverWait\nfrom selenium.webdriver.support import expected_conditions as EC\nfrom webdriver_manager.chrome import ChromeDriverManager\n\n# ---------------------------------------------------------------------------\n# Helper to start Flask server in background (development mode)\n# ---------------------------------------------------------------------------\n@pytest.fixture(scope="session", autouse=True)\ndef flask_server():\n    # Ensure .env variables are present (fallback defaults)\n    os.environ.setdefault("FLASK_ENV", "development")\n    # Start the server; it will listen on 127.0.0.1:5000\n    proc = subprocess.Popen(["python", "app.py"], cwd=os.path.abspath("./backend"))\n    # Wait a bit for the server to be ready (poll /)\n    timeout = 30\n    start = time.time()\n    while time.time() - start < timeout:\n        try:\n            import requests\n            r = requests.get("http://127.0.0.1:5000/")\n            if r.status_code == 200:\n                break\n        except Exception:\n            pass\n        time.sleep(0.5)\n    else:\n        proc.terminate()\n        pytest.fail("Flask server did not start within timeout")\n    yield\n    # Teardown – kill the server\n    proc.terminate()\n    proc.wait()\n\n# ---------------------------------------------------------------------------\n# Selenium driver fixture\n# ---------------------------------------------------------------------------\n@pytest.fixture\ndef driver():\n    options = webdriver.ChromeOptions()\n    # Run headless to work in CI environments\n    options.add_argument("--headless")\n    options.add_argument("--no-sandbox")\n    options.add_argument("--disable-dev-shm-usage")\n    service = ChromeService(ChromeDriverManager().install())\n    driver = webdriver.Chrome(service=service, options=options)\n    driver.set_window_size(1280, 800)\n    yield driver\n    driver.quit()\n\n# ---------------------------------------------------------------------------\n# Utility: login via API and store JWT in browser localStorage\n# ---------------------------------------------------------------------------\ndef api_login(email: str, password: str) -> str:\n    import requests\n    payload = {"email": email, "password": password}\n    resp = requests.post("http://127.0.0.1:5000/login", json=payload)\n    resp.raise_for_status()\n    data = resp.json()\n    return data["access_token"]\n\n# ---------------------------------------------------------------------------\ndef test_login_and_habits_flow(driver, flask_server):\n    # ---- 1️⃣ Ensure a test user exists (register if needed) ----\n    import requests, random, string\n    email = "e2e_test_user@example.com"\n    password = "Aa1!testPwd"\n    # Register – ignore 409 if already exists\n    try:\n        r = requests.post("http://127.0.0.1:5000/register", json={\n            "full_name": "E2E Test",\n            "email": email,\n            "password": password,\n            "confirm_password": password\n        })\n        if r.status_code not in (201, 409):\n            r.raise_for_status()\n    except Exception as e:\n        pytest.fail(f"User registration failed: {e}")\n\n    # ---- 2️⃣ Login via API, grab JWT ----\n    token = api_login(email, password)\n\n    # ---- 3️⃣ Open UI and inject token into localStorage ----\n    driver.get("http://127.0.0.1:5000/")\n    # Wait for the page to load (index.html is static)\n    WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.TAG_NAME, "body")))\n    # Store token – the app reads it from the Authorization header on AJAX calls,\n    # but for the sake of this demo we place it into localStorage under a known key.\n    driver.execute_script(f"window.localStorage.setItem('jwt', '{token}');")\n\n    # Refresh so subsequent fetches include the token (the UI can read it).\n    driver.refresh()\n    # ---- 4️⃣ Navigate to habits endpoint via direct XHR (simpler than UI clicks) ----\n    # Use Selenium to execute a fetch and capture the JSON response.\n    result = driver.execute_async_script(\n        "var callback = arguments[arguments.length - 1];"\n        "fetch('/habits?email=' + encodeURIComponent(arguments[0]), {\n            method: 'GET',\n            headers: {\n                'Authorization': 'Bearer ' + window.localStorage.getItem('jwt')\n            }\n        })\n        .then(r => r.json())\n        .then(data => callback(JSON.stringify(data)))\n        .catch(err => callback('ERROR:' + err));", email)\n    if result.startswith('ERROR:'):\n        pytest.fail(f"Fetching habits failed: {result}")\n    data = json.loads(result)\n    assert data["status"] == "success", "Habits endpoint did not return success"\n    # Optionally verify at least one habit exists (default list)\n    assert isinstance(data.get("habits"), list)\n\n    # ---- 5️⃣ Logout (clear token) ----\n    driver.execute_script("window.localStorage.removeItem('jwt');")\n    # Confirm token cleared\n    assert driver.execute_script("return window.localStorage.getItem('jwt');") is None\n\n    # End of test – if we reach here everything worked\n\n# ---------------------------------------------------------------------------\n# Additional tests can be added for other routes (e.g., create‑own habit) using the same token\n# ---------------------------------------------------------------------------\n
